package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="rsp_evaluation_evidence") public class EvaluationEvidence extends RspAuditedEntity{
 public enum OwnerType{STAGE_RESULT,PANEL_RATING,REFERENCE_CHECK,MEETING,RESOLUTION}public enum Classification{CONFIDENTIAL,HRMPSB_RESTRICTED}
 @Column(name="proceeding_id",nullable=false,length=36)private String proceedingId;@Column(name="candidate_id",length=36)private String candidateId;@Enumerated(EnumType.STRING)@Column(name="owner_type",nullable=false,length=40)private OwnerType ownerType;@Column(name="owner_id",nullable=false,length=36)private String ownerId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private Classification classification;@Column(name="original_filename",nullable=false,length=255)private String originalFilename;@Column(name="media_type",nullable=false,length=120)private String mediaType;@Column(name="byte_size",nullable=false)private long byteSize;@Column(name="checksum_sha256",nullable=false,length=64)private String checksum;@Column(name="storage_provider",nullable=false,length=30)private String storageProvider;@Column(name="storage_object_key",nullable=false,unique=true,length=500)private String storageObjectKey;@Column(name="retention_tag",nullable=false,length=100)private String retentionTag;@Column(name="uploaded_by",nullable=false,length=100)private String uploadedBy;@Column(name="uploaded_at",nullable=false)private Instant uploadedAt;
 protected EvaluationEvidence(){}public EvaluationEvidence(String agency,String proceeding,String candidate,OwnerType type,String owner,Classification classification,String filename,String media,long size,String checksum,String provider,String key,String retention,String actor,Instant at){super(agency);proceedingId=requiredText(proceeding,"proceedingId");candidateId=optionalText(candidate);ownerType=Objects.requireNonNull(type);ownerId=requiredText(owner,"ownerId");this.classification=Objects.requireNonNull(classification);originalFilename=requiredText(filename,"filename");mediaType=requiredText(media,"mediaType");if(size<1)throw new IllegalArgumentException("Evidence is empty");byteSize=size;this.checksum=requiredText(checksum,"checksum");if(this.checksum.length()!=64)throw new IllegalArgumentException("SHA-256 checksum is invalid");storageProvider=requiredText(provider,"storageProvider");storageObjectKey=requiredText(key,"storageObjectKey");retentionTag=requiredText(retention,"retentionTag");uploadedBy=requiredText(actor,"actor");uploadedAt=Objects.requireNonNull(at);}
 public String getProceedingId(){return proceedingId;}public String getCandidateId(){return candidateId;}public OwnerType getOwnerType(){return ownerType;}public String getOwnerId(){return ownerId;}public Classification getClassification(){return classification;}public String getOriginalFilename(){return originalFilename;}public String getMediaType(){return mediaType;}public long getByteSize(){return byteSize;}public String getChecksum(){return checksum;}public String getStorageProvider(){return storageProvider;}public String getStorageObjectKey(){return storageObjectKey;}public String getRetentionTag(){return retentionTag;}
}
